document.addEventListener("DOMContentLoaded", () => {
  // Navigation
  const navItems = document.querySelectorAll(".nav-item");
  const tabContents = document.querySelectorAll(".tab-content");

  navItems.forEach(item => {
    item.addEventListener("click", (e) => {
      e.preventDefault();
      // Remove active from all
      navItems.forEach(nav => nav.classList.remove("active"));
      tabContents.forEach(tab => tab.classList.remove("active"));
      
      // Add active to clicked
      item.classList.add("active");
      document.getElementById(item.dataset.target).classList.add("active");
    });
  });

  // Login Form
  const loginForm = document.getElementById("login-form");
  const loginOverlay = document.getElementById("login-overlay");
  const dashboard = document.getElementById("dashboard");

  loginForm.addEventListener("submit", (e) => {
    e.preventDefault();
    const btn = loginForm.querySelector("button");
    const originalText = btn.innerText;
    btn.innerText = "Authenticating...";
    btn.disabled = true;

    const formData = new URLSearchParams();
    formData.append("username", document.getElementById("username").value);
    formData.append("password", document.getElementById("password").value);

    // Send POST to /login
    fetch("/login", {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: formData
    })
    .then(response => {
      // Hide login, show dashboard
      loginOverlay.style.opacity = '0';
      setTimeout(() => {
        loginOverlay.classList.add("hidden");
        dashboard.classList.remove("hidden");
        // Start polling
        setInterval(pollData, 2000);
        pollData();
      }, 400);
    })
    .catch(err => {
      console.error(err);
      btn.innerText = "Error - Try Again";
      btn.disabled = false;
      setTimeout(() => { btn.innerText = originalText; }, 2000);
    });
  });

  // Data Polling
  function pollData() {
    fetch("/data.json")
      .then(res => res.json())
      .then(data => {
        if (data.status !== undefined) document.getElementById("status").innerText = data.status ? "Running" : "Idle";
        if (data.uptime !== undefined) document.getElementById("uptime").innerText = data.uptime;
        if (data.USBmode !== undefined) document.getElementById("USBmode").innerText = data.USBmode;
        if (data.heapUsagePc !== undefined) document.getElementById("heapUsage").style.width = data.heapUsagePc + "%";
        if (data.sdCardPercentFull !== undefined) document.getElementById("sdcard_capacity").style.width = data.sdCardPercentFull + "%";
        
        // Update Logs
        if (data.logMessages && data.logMessages.length > 0) {
          const logBox = document.getElementById("logBox");
          const isScrolledToBottom = logBox.scrollHeight - logBox.clientHeight <= logBox.scrollTop + 1;
          logBox.value = data.logMessages.join("\n");
          if (isScrolledToBottom) {
            logBox.scrollTop = logBox.scrollHeight;
          }
        }

        // Update File Tree
        if (data.fileListing) {
          const tree = document.getElementById("tree");
          const currentFiles = Array.from(tree.children).map(el => el.innerText);
          if (JSON.stringify(currentFiles) !== JSON.stringify(data.fileListing)) {
            tree.innerHTML = "";
            data.fileListing.forEach(file => {
              const div = document.createElement("div");
              div.className = "file-item";
              div.innerText = file;
              div.onclick = () => {
                document.getElementById("fileSelectionBox").value = file;
                document.getElementById("fileDownloadButton").disabled = false;
                document.getElementById("fileDeleteButton").disabled = false;
              };
              tree.appendChild(div);
            });
          }
        }
      })
      .catch(err => console.error("Polling error:", err));
  }
  
  // For development testing, you can bypass the login overlay by pressing escape
  document.addEventListener('keydown', (e) => {
    if(e.key === 'Escape' && !loginOverlay.classList.contains("hidden")) {
      loginOverlay.style.opacity = '0';
      setTimeout(() => {
        loginOverlay.classList.add("hidden");
        dashboard.classList.remove("hidden");
        setInterval(pollData, 2000);
        pollData();
      }, 400);
    }
  });

});